const inputData = $input.first().json;
try {
  const text = inputData.candidates?.[0]?.content?.parts?.[0]?.text;
  if (!text) throw new Error("No Gemini output text");
  const parsed = JSON.parse(text);
  return [{ json: { status: "success", auditedAt: new Date().toISOString(), ...parsed } }];
} catch (e) {
  return [{ json: { status: "fallback", error: e.message, auditedAt: new Date().toISOString(), ...{"tamperRiskLevel":"LOW","discrepancyPercentage":2.1,"masterMeterConsumptionKwh":14250,"submeterAggregatedKwh":13950,"unmeteredCommonAreaKwh":300,"flaggedMeters":[],"auditObservations":"Discrepancy of 2.1% is within standard CT coil line loss and common-area lift/lighting consumption.","recommendedInspectionOrders":[]} } }];
}
